//! 🌊️ Handcrafted persisted Flow parent and exact composed child handle.
use crate::standards::v1::subsets::any::schema::snapshot::FlowSnapshot;
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound}}};
fn invalid(message:impl Into<String>)->ValueError{ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,message)}
fn semantic_value_bytes(texts:[&str;6])->Result<usize,ValueError>{texts.into_iter().try_fold(16usize,|total,text|total.checked_add(text.len()).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Flow semantic value bytes overflow")))}
fn native_text(record:&semio_framework_dsl_record::RecordValue,id:u16)->Result<&str,ValueError>{match record.get(id){Some(semio_framework_dsl_record::FieldValue::Text(text))=>Ok(text),_=>Err(invalid("Flow requires its literal Text fields"))}}
fn native_record(record:&semio_framework_dsl_record::RecordValue,id:u16)->Result<&semio_framework_dsl_record::RecordValue,ValueError>{match record.get(id){Some(semio_framework_dsl_record::FieldValue::Record(value))=>Ok(value),_=>Err(invalid("Flow requires its literal child and reference Records"))}}
fn native_value_bytes(record:&semio_framework_dsl_record::RecordValue)->Result<usize,ValueError>{let child=native_record(record,1)?;let target=native_record(child,1)?;semantic_value_bytes([native_text(record,0)?,native_text(child,0)?,native_text(target,0)?,native_text(target,1)?,native_text(target,2)?,native_text(target,3)?])}
impl ArtifactSqliteSnapshot for FlowSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,c:&mut SqliteSnapshotControl<'_>,native_control: &mut semio_framework_os_kernel::NativeSnapshotDecodeOwner<'_, '_>)->Result<Self,ValueError>{c.check_rows(2)?;let maximum=c.limits().max_value_bytes;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record, snapshot_output, native,_body| { let constructed: Result<_, semio_framework_value::ValueError> = (|| {if native_value_bytes(record)?>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Flow native values exceed semantic byte limit"))}Self::__dsl_from_record_controlled(record,native)})(); *snapshot_output = Some(constructed?); Ok(()) },c,native_control)}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>,native_owner:&mut semio_framework_os_kernel::NativeSnapshotEncodeOwner<'_, '_>)->Result<store::io_schema::IoPayload,ValueError>{c.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;c.check_rows(2)?;let target=&self.content.target;let dialect=&target.dialect;c.check_value_bytes(semantic_value_bytes([&self.schema,&self.content.child_id,&target.artifact_id,&dialect.artifact_kind,&dialect.standard,&dialect.subset])?)?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),c,native_owner)}
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let result=(||->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;let target=&self.content.target;let dialect=&target.dialect;p.insert("flow_document",&[Cell::Text(&self.schema)])?;p.insert("flow_content",&[Cell::Text(&self.content.child_id),Cell::Text(&target.artifact_id),Cell::Text(&dialect.artifact_kind),Cell::Text(&dialect.standard),Cell::Text(&dialect.subset)])?;p.finish()})();result}
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let result=(||->Result<Self,ValueError>{validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let document=d.table("flow_document")?.single_row()?;let content=d.table("flow_content")?.single_row()?;if document.rowid!=1||content.rowid!=1||document.integer(0)?!=1||content.integer(0)?!=1||document.values.len()!=2||content.values.len()!=6{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Flow requires exact identity-1 parent and child rows"))}let mut r=Reconstruction::new(c)?;let schema=r.text(document.text(1)?)?;let child_id=r.text(content.text(1)?)?;let artifact_id=r.text(content.text(2)?)?;let artifact_kind=r.text(content.text(3)?)?;let standard=r.text(content.text(4)?)?;let subset=r.text(content.text(5)?)?;r.checkpoint()?;Ok(Self{schema,content:store::ArtifactChild::new(child_id,semio_framework_artifact_reference::ArtifactRef{artifact_id,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind,standard,subset}})})})();result}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let result=(||->Result<(),ValueError>{let mut b=NativeEncodingBound::new(c)?;b.add(4096)?;let target=&self.content.target;let dialect=&target.dialect;for text in[&self.schema,&self.content.child_id,&target.artifact_id,&dialect.artifact_kind,&dialect.standard,&dialect.subset]{b.repeated(text.len(),16)?}b.finish()})();result}
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.flow.flow"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("Flow dialect differs from its owned wildcard")))}if d.table("flow_document").map_err(store::io_schema::IoError::from_value_error)?.single_row().map_err(store::io_schema::IoError::from_value_error)?.text(1).map_err(store::io_schema::IoError::from_value_error)?!=self.schema{return Err(store::io_schema::IoError::from_value_error(invalid("Flow projected schema differs")))}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(store::io_schema::IoError::from_value_error)?;Ok(store::io_schema::IoOutcome::clean(()))}
}

